import { fetchAllPages } from '$lib/server/utils/supabasePaging.js';

const DEFAULT_PAGE_SIZE = 1000;
const DEFAULT_CHUNK_SIZE = 500;

function chunkArray(items, chunkSize) {
  const chunks = [];
  for (let i = 0; i < items.length; i += chunkSize) {
    chunks.push(items.slice(i, i + chunkSize));
  }
  return chunks;
}

function stripAutoFields(record) {
  // Remove fields that should be generated by the database.
  const { id, created_at, updated_at, ...rest } = record;
  return rest;
}

export function buildProgressInserts(records, targetQuizId, userId) {
  return (records || []).map((record) => ({
    ...stripAutoFields(record),
    quiz_id: targetQuizId,
    user_id: userId
  }));
}

export function buildSessionInsert(record, targetQuizId, userId) {
  return {
    ...stripAutoFields(record),
    quiz_id: targetQuizId,
    user_id: userId
  };
}

export function buildPlayInserts(records, targetQuizId, sessionIdMap, userId) {
  const inserts = [];
  let skipped = 0;

  for (const record of records || []) {
    const mappedSessionId = sessionIdMap.get(record.session_id);
    if (!mappedSessionId) {
      skipped++;
      continue;
    }

    inserts.push({
      ...stripAutoFields(record),
      quiz_id: targetQuizId,
      session_id: mappedSessionId,
      user_id: userId
    });
  }

  return { inserts, skipped };
}

export async function cloneTrainingData(
  supabaseAdmin,
  { sourceQuizId, targetQuizId, userId, pageSize = DEFAULT_PAGE_SIZE, chunkSize = DEFAULT_CHUNK_SIZE }
) {
  const result = {
    progress: 0,
    sessions: 0,
    plays: 0,
    skippedPlays: 0
  };

  const { data: progressRecords, error: progressError } = await fetchAllPages(
    () =>
      supabaseAdmin
        .from('training_progress')
        .select('*')
        .eq('user_id', userId)
        .eq('quiz_id', sourceQuizId)
        .order('id', { ascending: true }),
    { pageSize }
  );

  if (progressError) {
    throw new Error(`Failed to load training progress: ${progressError.message}`);
  }

  const progressInserts = buildProgressInserts(progressRecords, targetQuizId, userId);
  const progressChunks = chunkArray(progressInserts, chunkSize);

  for (const chunk of progressChunks) {
    if (chunk.length === 0) continue;
    const { error } = await supabaseAdmin.from('training_progress').insert(chunk);
    if (error) {
      throw new Error(`Failed to insert training progress: ${error.message}`);
    }
    result.progress += chunk.length;
  }

  const { data: sessionRecords, error: sessionError } = await fetchAllPages(
    () =>
      supabaseAdmin
        .from('training_sessions')
        .select('*')
        .eq('user_id', userId)
        .eq('quiz_id', sourceQuizId)
        .order('started_at', { ascending: true }),
    { pageSize }
  );

  if (sessionError) {
    throw new Error(`Failed to load training sessions: ${sessionError.message}`);
  }

  const sessionIdMap = new Map();

  for (const session of sessionRecords || []) {
    const sessionInsert = buildSessionInsert(session, targetQuizId, userId);
    const { data, error } = await supabaseAdmin
      .from('training_sessions')
      .insert(sessionInsert)
      .select('id')
      .single();

    if (error) {
      throw new Error(`Failed to insert training session: ${error.message}`);
    }

    sessionIdMap.set(session.id, data.id);
    result.sessions += 1;
  }

  const { data: playRecords, error: playError } = await fetchAllPages(
    () =>
      supabaseAdmin
        .from('training_session_plays')
        .select('*')
        .eq('user_id', userId)
        .eq('quiz_id', sourceQuizId)
        .order('played_at', { ascending: true }),
    { pageSize }
  );

  if (playError) {
    throw new Error(`Failed to load training plays: ${playError.message}`);
  }

  const { inserts: playInserts, skipped } = buildPlayInserts(
    playRecords,
    targetQuizId,
    sessionIdMap,
    userId
  );
  const playChunks = chunkArray(playInserts, chunkSize);

  for (const chunk of playChunks) {
    if (chunk.length === 0) continue;
    const { error } = await supabaseAdmin.from('training_session_plays').insert(chunk);
    if (error) {
      throw new Error(`Failed to insert training plays: ${error.message}`);
    }
    result.plays += chunk.length;
  }

  result.skippedPlays = skipped;
  return result;
}
